CREATE EXTENSION IF NOT EXISTS citext;
CREATE TABLE users (id bigserial PRIMARY KEY, username citext NOT NULL UNIQUE, email citext NOT NULL UNIQUE, trust_level smallint NOT NULL DEFAULT 0 CHECK (trust_level BETWEEN 0 AND 4), ip_address inet, created_at timestamp without time zone NOT NULL DEFAULT now(), last_seen_at timestamp without time zone);
CREATE TABLE categories (id serial PRIMARY KEY, name varchar(50) NOT NULL UNIQUE, color char(6) NOT NULL DEFAULT '0088CC', position integer, parent_category_id integer REFERENCES categories (id));
CREATE TABLE topics (id bigserial PRIMARY KEY, title varchar(255) NOT NULL, category_id integer NOT NULL REFERENCES categories (id), user_id bigint NOT NULL REFERENCES users (id), views integer NOT NULL DEFAULT 0, posts_count integer NOT NULL DEFAULT 0, pinned_at timestamp without time zone, closed boolean NOT NULL DEFAULT false, created_at timestamp without time zone NOT NULL DEFAULT now());
CREATE TABLE posts (id bigserial PRIMARY KEY, topic_id bigint NOT NULL REFERENCES topics (id) ON DELETE CASCADE, user_id bigint REFERENCES users (id), post_number integer NOT NULL, raw text NOT NULL, cooked text, reply_to_post_number integer, like_count integer NOT NULL DEFAULT 0, created_at timestamp without time zone NOT NULL DEFAULT now(), UNIQUE (topic_id, post_number));
CREATE TABLE post_likes (post_id bigint NOT NULL REFERENCES posts (id) ON DELETE CASCADE, user_id bigint NOT NULL REFERENCES users (id) ON DELETE CASCADE, created_at timestamp without time zone NOT NULL DEFAULT now(), PRIMARY KEY (post_id, user_id));
CREATE TABLE user_badges (id bigserial PRIMARY KEY, user_id bigint NOT NULL REFERENCES users (id), badge_id integer NOT NULL, granted_at timestamp without time zone NOT NULL, UNIQUE (user_id, badge_id));
